const negotiationTerms = ['orçamento', 'orcamento', 'preço', 'preco', 'prazo', 'contrato', 'proposta', 'reunião', 'reuniao', 'fechar', 'escopo', 'valor', 'disponibilidade', 'interesse'];
const optOutTerms = ['não entrar em contato', 'nao entrar em contato', 'remover', 'remova', 'não quero receber', 'nao quero receber', 'unsubscribe', 'stop', 'pare de enviar'];

return $input.all().map(({ json }) => {
  const text = [json.subject, json.snippet, json.textPlain, json.text].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');
  const matchedTerms = negotiationTerms.filter((term) => text.includes(term));
  const optOut = optOutTerms.some((term) => text.includes(term));
  return { json: { ...json, negotiation_signal: matchedTerms.length > 0, opt_out_signal: optOut, matched_terms: matchedTerms, alert_subject: optOut ? 'Pedido de não contato recebido' : `Oportunidade de negociação: ${json.subject || 'nova resposta por e-mail'}` };
}).filter(({ json }) => json.negotiation_signal || json.opt_out_signal);
